                start = (i * i) >> 1
                sieve[start::i] = b'\x00' * ((size - 1 - start) // i + 1)
        return sieve.count(1) + 1

    r = isqrt(m)
    small = [(i + 1) >> 1 for i in range(r + 1)]
    large = [0] * (r + 1)
