import sys
from math import isqrt

def count_primes(n: int) -> int:
    if n <= 2:
        return 0
    if n <= 3:
        return 1
    m = n - 1
    if m < 100000:
        size = n // 2
        sieve = bytearray(b'\x01') * size
        sieve[0] = 0
        for i in range(3, isqrt(n) + 1, 2):
            if sieve[i >> 1]:
                start = (i * i) >> 1
                sieve[start::i] = b'\x00' * ((size - 1 - start) // i + 1)
        return sieve.count(1) + 1

    r = isqrt(m)
    small = [(i + 5) // 6 + (i + 1) // 6 for i in range(r + 1)]
    large = [0] + [((m // i + 5) // 6 + (m // i + 1) // 6) for i in range(1, r + 1)]
    coprime6 = [i for i in range(1, r + 1, 2) if i % 3]

    for p in range(5, r + 1, 2):
        if small[p] > small[p - 1]:
            sp = small[p - 1]
            mp = m // p
            max_i = min(r, mp // p)
            limit1 = min(r // p, max_i)
            for i in coprime6:
                if i > limit1:
                    break
                large[i] -= large[i * p] - sp
            for i in coprime6:
                if i <= limit1:
                    continue
                if i > max_i:
                    break
                large[i] -= small[mp // i] - sp
            for q in range(r // p, p - 1, -1):
                d = small[q] - sp
                qp = q * p
                end = r + 1 if qp + p > r else qp + p
                for v in range(qp, end):
                    small[v] -= d

    return large[1] + 1

if __name__ == "__main__":
    print(count_primes(int(sys.argv[1])))
